from gurobipy import *

def solve_problem():
    m = Model("Battlefield_Logistics")
    m.setParam("TimeLimit", 100)  # Set time limit to 100 seconds

    # Data
    depots = list(range(4))  # D0..D3
    units = list(range(9))  # U0..U8
    supplies = list(range(3))  # S0..S2
    days = list(range(4))  # Day0..Day3

    demands = [[[23.22, 14.99, 21.9, 16.7], [38.01, 44.22, 28.68, 18.01], [13.73, 23.27, 39.89, 10.03]], [[17.91, 22.38, 46.1, 41.65], [13.92, 21.25, 24.81, 14.17], [22.6, 15.16, 38.05, 38.28]], [[41.6, 15.46, 42.85, 20.6], [26.03, 14.19, 30.29, 28.6], [47.74, 13.66, 35.9, 27.37]], [[35.83, 37.94, 34.47, 22.41], [47.85, 20.55, 43.24, 12.72], [33.02, 43.97, 25.26, 21.43]], [[32.67, 16.01, 32.56, 21.49], [27.6, 48.99, 41.31, 17.75], [17.45, 23.29, 48.33, 37.83]], [[21.63, 15.52, 45.1, 35.95], [42.88, 23.93, 31.62, 22.38], [41.15, 13.66, 38.41, 31.2]], [[25.63, 44.45, 26.86, 26.93], [35.73, 10.91, 25.48, 48.28], [40.88, 38.39, 28.73, 18.4]], [[25.55, 13.23, 35.42, 14.47], [20.7, 40.71, 24.91, 40.35], [17.87, 33.51, 10.18, 19.96]], [[13.23, 34.93, 22.37, 33.79], [20.53, 41.86, 25.93, 25.89], [35.01, 32.77, 18.14, 17.14]]]
    depot_supplies = [[[77.6, 77.83, 78.2, 46.85], [96.39, 69.87, 90.13, 72.4], [100.04, 72.74, 96.9, 45.79]], [[88.87, 71.92, 81.0, 68.13], [63.46, 58.8, 59.67, 47.16], [67.45, 84.35, 96.67, 63.33]], [[80.95, 78.52, 114.69, 56.83], [99.45, 69.47, 71.37, 83.28], [85.9, 52.24, 101.44, 57.34]], [[69.33, 43.35, 110.61, 62.05], [73.83, 89.26, 76.49, 65.45], [56.93, 85.57, 89.88, 68.94]]]
    transport_costs = [[3.61, 3.07, 4.61, 1.8, 2.6, 4.32, 4.64, 3.56, 3.17], [3.56, 4.88, 1.88, 3.72, 1.96, 3.37, 2.58, 2.87, 3.86], [2.79, 3.32, 2.57, 4.82, 2.58, 3.23, 3.69, 2.96, 3.77], [4.99, 3.73, 2.35, 3.44, 3.27, 3.33, 2.05, 2.69, 1.88]]
    risk_costs = [[157.57, 133.41, 65.05, 162.02, 178.7, 164.45, 161.68, 142.77, 63.63], [190.15, 61.21, 154.1, 97.81, 152.68, 153.73, 161.47, 183.3, 96.62], [69.72, 90.21, 51.01, 58.12, 142.22, 57.4, 106.37, 103.14, 171.39], [55.73, 120.39, 95.68, 182.61, 93.3, 90.8, 174.14, 129.91, 162.91]]
    supply_volumes = [1.95, 1.2, 0.86]
    penalty_costs = [85.42, 51.45, 83.42]
    vehicle_cost = 10.0
    vehicle_capacity = 144.0
    total_vehicles = 12

    # Decision variables
    # Flow_D{d}_U{u}_S{s}_Day{t}: Amount of supply s from depot d to unit u on day t
    flows = {}
    for t in days:
        for d in depots:
            for u in units:
                for s in supplies:
                    flows[(d, u, s, t)] = m.addVar(lb=0.0, vtype=GRB.CONTINUOUS, name=f"Flow_D{d}_U{u}_S{s}_Day{t}")

    # Slack_U{u}_S{s}_Day{t}: Shortage of supply s at unit u on day t
    slacks = {}
    for t in days:
        for u in units:
            for s in supplies:
                slacks[(u, s, t)] = m.addVar(lb=0.0, vtype=GRB.CONTINUOUS, name=f"Slack_U{u}_S{s}_Day{t}")

    # Veh_D{d}_U{u}_Day{t}: Number of vehicles on route d->u on day t
    vehicles = {}
    for t in days:
        for d in depots:
            for u in units:
                vehicles[(d, u, t)] = m.addVar(lb=0.0, vtype=GRB.INTEGER, name=f"Veh_D{d}_U{u}_Day{t}")

    # Route_D{d}_U{u}_Day{t}: Route d->u is active on day t (binary)
    routes = {}
    for t in days:
        for d in depots:
            for u in units:
                routes[(d, u, t)] = m.addVar(vtype=GRB.BINARY, name=f"Route_D{d}_U{u}_Day{t}")

    # Objective: Minimize total cost (transport + penalty + vehicle + risk)
    obj = quicksum(
        transport_costs[d][u] * flows[(d, u, s, t)]
        for t in days for d in depots for u in units for s in supplies
    )
    obj += quicksum(
        penalty_costs[s] * slacks[(u, s, t)]
        for t in days for u in units for s in supplies
    )
    obj += quicksum(
        vehicle_cost * vehicles[(d, u, t)]
        for t in days for d in depots for u in units
    )
    obj += quicksum(
        risk_costs[d][u] * routes[(d, u, t)]
        for t in days for d in depots for u in units
    )
    m.setObjective(obj, GRB.MINIMIZE)

    # Depot capacity constraints: Total outflow <= supply
    for t in days:
        for d in depots:
            for s in supplies:
                m.addConstr(
                    quicksum(flows[(d, u, s, t)] for u in units) <= depot_supplies[d][s][t],
                    name=f"DepotCap_D{d}_S{s}_Day{t}"
                )

    # Demand constraints: Inflow + slack >= demand
    for t in days:
        for u in units:
            for s in supplies:
                m.addConstr(
                    quicksum(flows[(d, u, s, t)] for d in depots) + slacks[(u, s, t)] >= demands[u][s][t],
                    name=f"Demand_U{u}_S{s}_Day{t}"
                )

    # Vehicle capacity constraints: Total volume <= vehicles * capacity
    for t in days:
        for d in depots:
            for u in units:
                m.addConstr(
                    quicksum(supply_volumes[s] * flows[(d, u, s, t)] for s in supplies) <= vehicle_capacity * vehicles[(d, u, t)],
                    name=f"VehCap_D{d}_U{u}_Day{t}"
                )

    # Route activation constraints: vehicles <= total_vehicles * route
    for t in days:
        for d in depots:
            for u in units:
                m.addConstr(
                    vehicles[(d, u, t)] <= total_vehicles * routes[(d, u, t)],
                    name=f"RouteAct_D{d}_U{u}_Day{t}"
                )

    # Fleet size constraints: Total vehicles <= total_vehicles
    for t in days:
        m.addConstr(
            quicksum(vehicles[(d, u, t)] for d in depots for u in units) <= total_vehicles,
            name=f"FleetSize_Day{t}"
        )

    m.optimize()
    return m
